ANCIEN = "ETSL — Établissements Techniques et Services Logistiques"
NOUVEAU = "ETSL — Entreprise de Tuyauterie, Soudure et Location"


def corriger_raison_sociale(apps, schema_editor):
    """En-tete de facture : l'ancien nom (erreur du modele provisoire) est remplace par la raison sociale ETSL."""
    ModeleFacture = apps.get_model("comptabilite", "ModeleFacture")
    for m in ModeleFacture.objects.filter(entete__contains="Techniques et Services Logistiques"):
        m.entete = m.entete.replace(ANCIEN, NOUVEAU).replace(
            "Établissements Techniques et Services Logistiques", "Entreprise de Tuyauterie, Soudure et Location")
        m.save(update_fields=["entete"])


